/* ================= assets/site.css : append as a new block BEFORE the "REDUCED MOTION" section (line ~945). Every selector is prefixed html.story.snake (or is a default display:none for a new element), so no html.film rule changes and the reduced-motion story (never .snake) is untouched. ================= */

/* ============================================================
   THE PHONE SNAKE (html.story.snake): the cloche film pinned behind the
   first screen, the lid lifting as the words scroll away, and the line
   born from the mark running down the left edge of the page to the
   resolve. site.js adds .snake on a portrait story screen up to 1024px
   without reduced motion, and creates every .snk* element itself.
   ============================================================ */
html.story.snake{
  --pin:250vh;--pin:250lvh;                               /* the film's pinned run; PIN in site.js is the same number */
  --stage-pt:calc(var(--hdr-h) + clamp(28px,6vh,64px));   /* .stage's own padding-top, repeated so the first screen can be sized */
  --rail:calc(var(--gut) * .5 + 1px);                     /* the line's rest x: the middle of the gutter, a hair left (11px on a 390 phone) */
}

/* the first screen: the words sit in the first (small) viewport, the rest of the band is the pin's run */
html.story.snake .band--hero{
  display:grid;align-items:end;padding:0;
  grid-template-rows:calc(100vh - var(--stage-pt)) 1fr;
  grid-template-rows:calc(100svh - var(--stage-pt)) 1fr;
  min-height:calc(var(--pin) - var(--stage-pt));
}
html.story.snake .band--hero .band__in{grid-row:1;padding-bottom:clamp(28px,5vh,48px)}
/* the still is the film now */
html.story.snake .act--still{display:none}
/* the bands and props paint over the film */
html.story.snake .band,html.story.snake .act{position:relative;z-index:2}
/* the story's rising tick: the snake carries that meaning here */
html.story.snake .band:not(.band--hero) .band__in::before{display:none}

/* ---- the film, behind: a box as tall as the pin, its frame stuck to the top of the screen ---- */
html.story.snake .hero{
  display:block;position:absolute;top:0;left:0;right:0;height:var(--pin);z-index:0;
  overflow:visible;pointer-events:none;background:none;
}
html.story.snake .hero.off{visibility:hidden}
html.story.snake .hero__frame{
  position:-webkit-sticky;position:sticky;top:0;left:auto;
  width:100%;height:100vh;height:100lvh;
  overflow:hidden;transform:none;background:none;
}
/* the poster, the video and the canvas share one box: site.js layoutFilm() sets --pl/--pt/--pw/--ph
   (the encode scaled so the mark is MARKW of the screen, centred on the mark, MARKY down the screen) */
html.story.snake .snk__poster,html.story.snake .hero__video,html.story.snake .hero__film{
  position:absolute;inset:auto;left:var(--pl,0px);top:var(--pt,0px);width:var(--pw,100%);height:var(--ph,100%);
  -webkit-mask-image:linear-gradient(180deg,transparent 0,#000 14%,#000 86%,transparent 100%);
  mask-image:linear-gradient(180deg,transparent 0,#000 14%,#000 86%,transparent 100%);
}
html.story.snake .snk__poster{display:block;background:#000 center / 100% 100% no-repeat}
html.story.snake .hero__video,html.story.snake .hero__film{display:none;opacity:0;transition:opacity .6s var(--ease)}
html.story.snake .hero.wc .hero__film{display:block}
html.story.snake .hero:not(.wc) .hero__video{display:block}
html.story.snake .hero.video-ready .hero__film,html.story.snake .hero.video-ready .hero__video{opacity:1}
/* the blur under the words: a class, not blur(0), so no filter layer is paid for once the words have gone */
html.story.snake .hero.is-blur .hero__film,html.story.snake .hero.is-blur .hero__video{filter:blur(var(--hb,6px))}
html.story.snake .hero__pulses,html.story.snake .hero__ring{display:none}
/* the words' ground: heavy at the foot under the words, light under the header; --hs eases it off as the words leave */
html.story.snake .hero__frame::after{
  content:"";position:absolute;inset:0;pointer-events:none;
  background:linear-gradient(180deg,rgba(10,10,10,.55) 0%,rgba(10,10,10,0) 20%,rgba(10,10,10,0) 46%,rgba(10,10,10,.8) 74%,rgba(10,10,10,.94) 100%);
  opacity:var(--hs,1);
}

/* ---- the two drawings and the tip ---- */
.snk,.snkc,.snk__tip,.snk__poster{display:none}
html.story.snake .snk{display:block;position:absolute;left:0;top:0;z-index:3;overflow:visible;pointer-events:none}
html.story.snake .snkc{display:block;position:absolute;left:0;top:0;width:100%;height:100%;z-index:2;overflow:visible;pointer-events:none}
html.story.snake .snk__tip{
  display:block;position:absolute;left:0;top:0;z-index:4;width:72px;height:72px;margin:-36px 0 0 -36px;
  border-radius:50%;pointer-events:none;opacity:0;will-change:transform,opacity;
  background:radial-gradient(circle,#FFF8EC 0,#FFF8EC 2.2px,rgba(255,240,214,.6) 3.6px,rgba(255,214,160,.24) 9px,rgba(255,208,150,.07) 20px,rgba(255,208,150,0) 36px);
}
/* the threads: the desktop's stack at hairline size. dasharray on the group, inherited by the uses */
.snk__g{fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:var(--L,1);stroke-dashoffset:var(--off,var(--L,1))}
.snk__t--case{stroke:#000;stroke-width:5px;opacity:.55}
.snk__t--glow{stroke:url(#snkglit);stroke-width:10px;opacity:.16}
.snk__t--body{stroke:url(#snkg);stroke-width:2.2px}
.snk__t--core{stroke:#FFF6E8;stroke-width:.8px;opacity:.5}
.snkc .snk__t--glow{stroke:url(#snkglitc)}
.snkc .snk__t--body{stroke:url(#snkgc)}
/* the loop: drawn in the rail's colours, then the mark's own sweep takes it as it thickens into the ribbon */
.snk__g--loop{--lw:2.4px;--la:0;--lb:0}
.snk__t--lglow{stroke:url(#infg);stroke-width:calc(var(--lw) * 2.6);opacity:calc(.14 * (1 - var(--lb)))}
.snk__t--lbody{stroke:url(#snkg);stroke-width:var(--lw);opacity:calc(1 - var(--la))}
.snk__t--lring{stroke:url(#infg);stroke-width:var(--lw);opacity:calc(var(--la) * (1 - var(--lb)))}
/* the real mark waits for the line (--rb set by site.js); the story's own reveal stands aside for it */
html.js.story.snake .act--mark,html.js.story.snake .act--mark.in{opacity:var(--rb,0);transform:none;transition:none}

/* ================= assets/v-editorial.css : append after "FINE TUNE: the phone and reduced-motion story" (line ~620). The look only. ================= */
/* the first screen's words over the film: the same type, given a foot to stand on */
html[data-v="editorial"].story.snake .band--hero .sub{color:var(--ink)}
html[data-v="editorial"].story.snake .band--hero .hl--hero{text-shadow:0 2px 14px rgba(0,0,0,.5)}
html[data-v="editorial"].story.snake .hero__frame::after{
  background:linear-gradient(180deg,rgba(10,10,10,.55) 0%,rgba(10,10,10,0) 20%,rgba(10,10,10,0) 46%,rgba(10,10,10,.82) 74%,rgba(10,10,10,.95) 100%);
}
/* the tablet: the gutter is wider, the line keeps to its middle */
@media (min-width:600px){html[data-v="editorial"].story.snake{--rail:calc(var(--gut) * .5)}}

