/* ============================================================
   THE PHONE SNAKE. New section in assets/site.js, inserted after filmFallback()
   and before enableFilm() (line ~1425). Reuses clamp, smooth, track, setVar,
   setProp, toggle, drop, sample, filmFrame, requestSeek, dropFrames,
   initHeroOnce, sizeFilmCanvas. Desktop code paths are not edited except for
   the six one-line hooks listed at the end.
   ============================================================ */

/* ---- the gate: story + portrait + up to 1024 wide + no reduced motion + the parts exist ---- */
var snakeMq = matchMedia('(orientation: portrait) and (max-width: 1024px)');
var snakeOn = false, SN = null;                    /* SN: the built geometry */
function snakeWanted() {
  return root.classList.contains('story') && !reduced() && snakeMq.matches &&
    !!film && !!hero && !!heroFrame && !!markAct && 'getTotalLength' in SVGPathElement.prototype;
}

/* ---- the numbers (scroll in units of LVH = the frame's height = 100lvh) ---- */
var PIN = 2.5;                        /* = --pin. the frame un-sticks at u = PIN - 1 */
var K = .62;                          /* the reading line: the drawn end sits K*LVH below the top of the screen */
var MARKW = .78, MARKY = .44;         /* the mark's width as a share of the screen, and its centre down the first screen */
var TT = [[.45, 0], [1.0, 4.2], [1.15, 5.4], [1.5, 6.4], [2.5, 7.6]];   /* u -> film seconds; 7.6 s is the last intact mark before the unravel */
var U_BLUR = [.30, .80], U_GLOW = [1.0, 1.15], U_BIRTH = [1.15, 1.5];
var LOOP_RUN = 1.15;                  /* mark heights of reading-line travel that draw the loop */
var RB_RUN = .30;                     /* LVH of travel for the ribbon crossfade */
/* the encodes. the phone crop is 960x1080 of the 1920x1080 frame at x=797 (crop=960:1080:797:0),
   so the mark's centre (.665,.51 of the 16:9 frame) is (.50,.51) of the crop and the mark is .66 of its width.
   the 16:9 file stays the fallback (a page that loaded as film and then rotated already holds it). */
var ENC_P  = { url: 'assets/hero-scrub-p.mp4?v=<sha10>', poster: 'assets/hero-poster-p.jpg?v=<sha10>', w: 960,  h: 1080, mx: .50,  my: .51, markW: .66 };
var ENC_16 = { url: VIDEO_URL,                            poster: 'assets/hero-poster.jpg?v=fcb47a6d59', w: 1920, h: 1080, mx: .665, my: .51, markW: .33 };
function encOf() { return (FD && FD.mp4.width === 1920) || (!FD && heroVideo && heroVideo.videoWidth === 1920) ? ENC_16 : ENC_P }

/* ---- DOM, made once ---- */
var snk = null, snkc = null, snkTip = null, snkPoster = null, snkLine = null, snkLoop = null, snkCurl = null, snkG = {};
var NS = 'http://www.w3.org/2000/svg';
function el(n, a, p) { var e = document.createElementNS(NS, n); for (var k in a) e.setAttribute(k, a[k]); if (p) p.appendChild(e); return e }
function grad(id, stops, p) { var g = el('linearGradient', { id: id, gradientUnits: 'userSpaceOnUse', spreadMethod: 'repeat', x1: 0, y1: 0, x2: 0, y2: 1 }, p);
  stops.forEach(function (s, i) { el('stop', { offset: (i * 100 / 7).toFixed(1) + '%', 'stop-color': s }, g) }); return g }
var SPEC = ['#E5322B','#F2912F','#F3CB3C','#5CB246','#0FA3C2','#2E5FA8','#7A3E97','#D51C73'];
var SPECL = ['#FF6A5E','#FFAD52','#FFDE55','#86E070','#3ED6ED','#7AA6FF','#C58BF0','#FF6FB4'];
function threads(g, href, names) { names.forEach(function (n) { el('use', { 'class': 'snk__t snk__t--' + n, href: href }, g) }) }
function makeSnakeDom() {
  if (snk) return;
  snk = el('svg', { 'class': 'snk', id: 'snk', 'aria-hidden': 'true', focusable: 'false' });
  var d = el('defs', {}, snk);
  snkG.g = grad('snkg', SPEC, d); snkG.gl = grad('snkglit', SPECL, d);
  snkLine = { path: el('path', { id: 'snkPath', d: 'M0 0' }, d), g: el('g', { 'class': 'snk__g snk__g--line' }, snk) };
  threads(snkLine.g, '#snkPath', ['case', 'glow', 'body', 'core']);
  snkLoop = { path: el('path', { id: 'snkLoop', d: 'M0 0' }, d), g: el('g', { 'class': 'snk__g snk__g--loop' }, snk) };
  threads(snkLoop.g, '#snkLoop', ['lglow', 'lbody', 'lring']);
  snkc = el('svg', { 'class': 'snkc', id: 'snkc', 'aria-hidden': 'true', focusable: 'false' });
  var dc = el('defs', {}, snkc);
  snkG.gc = grad('snkgc', SPEC, dc); snkG.glc = grad('snkglitc', SPECL, dc);
  snkCurl = { path: el('path', { id: 'snkCurl', d: 'M0 0' }, dc), g: el('g', { 'class': 'snk__g snk__g--curl' }, snkc) };
  threads(snkCurl.g, '#snkCurl', ['case', 'glow', 'body', 'core']);
  snkTip = document.createElement('i'); snkTip.className = 'snk__tip'; snkTip.id = 'snkTip'; snkTip.setAttribute('aria-hidden', 'true');
  snkPoster = document.createElement('i'); snkPoster.className = 'snk__poster'; snkPoster.setAttribute('aria-hidden', 'true');
  film.appendChild(snk); film.appendChild(snkTip);
  heroFrame.insertBefore(snkPoster, heroFrame.firstChild); heroFrame.appendChild(snkc);
}

/* ---- the film's box: the encode scaled so the mark is MARKW of the screen, the mark's centre at (bw/2, MARKY*bh) ---- */
function layoutFilm() {
  var E = encOf(), bw = heroFrame.clientWidth, bh = heroFrame.clientHeight;   /* bh = LVH */
  var s = MARKW * bw / (E.markW * E.w);
  s = Math.min(s, bh * .92 / E.h);                      /* a short screen: never taller than the screen */
  s *= 1.03;                                            /* room for the blur's soft edge under the mask */
  var dw = E.w * s, dh = E.h * s;
  var pl = bw * .5 - dw * E.mx, pt = bh * MARKY - dh * E.my;
  [['--pl', pl], ['--pt', pt], ['--pw', dw], ['--ph', dh]].forEach(function (v) { setVar(heroFrame, v[0], v[1], .5, 'px') });
  snkPoster.style.backgroundImage = "url('" + E.poster + "')";
  return { bw: bw, bh: bh, mx: bw * .5, my: bh * MARKY };  /* M: the mark's centre, frame-local */
}

/* ---- geometry, page px relative to section.film ---- */
function pageTop(e) { return e.getBoundingClientRect().top + (window.scrollY || 0) }   /* bands are never transformed */
function offTop(e) { var y = 0; while (e && e !== film) { y += e.offsetTop; e = e.offsetParent } return y }  /* .act props are (translateY(18px) before .in): use layout offsets */
function crCubics(pts) {              /* Catmull-Rom through pts -> "C" segments; pts[0] and the last are repeated as ghosts */
  var d = '', n = pts.length;
  for (var i = 0; i < n - 1; i++) {
    var p0 = pts[Math.max(0, i - 1)], p1 = pts[i], p2 = pts[i + 1], p3 = pts[Math.min(n - 1, i + 2)];
    var c1x = p1[0] + (p2[0] - p0[0]) / 6, c1y = p1[1] + (p2[1] - p0[1]) / 6;
    var c2x = p2[0] - (p3[0] - p1[0]) / 6, c2y = p2[1] - (p3[1] - p1[1]) / 6;
    d += ' C' + c1x.toFixed(1) + ' ' + c1y.toFixed(1) + ' ' + c2x.toFixed(1) + ' ' + c2y.toFixed(1) + ' ' + p2[0].toFixed(1) + ' ' + p2[1].toFixed(1);
  }
  return d;
}
function atY(map, y) {                /* the (monotone in y) rail: arc length at page y */
  var ys = map.ys, lo = 0, hi = map.n;
  if (y <= ys[0]) return 0; if (y >= ys[hi]) return map.L;
  while (hi - lo > 1) { var m = (lo + hi) >> 1; if (ys[m] <= y) lo = m; else hi = m }
  var t = (y - ys[lo]) / ((ys[hi] - ys[lo]) || 1);
  return map.ls[lo] + (map.ls[hi] - map.ls[lo]) * t;
}
function atL(map, l) {                /* point at arc length, from the samples (no layout call per frame) */
  var ls = map.ls, lo = 0, hi = map.n;
  l = clamp(l, 0, map.L);
  while (hi - lo > 1) { var m = (lo + hi) >> 1; if (ls[m] <= l) lo = m; else hi = m }
  var t = (l - ls[lo]) / ((ls[hi] - ls[lo]) || 1);
  return { x: map.xs[lo] + (map.xs[hi] - map.xs[lo]) * t, y: map.ys[lo] + (map.ys[hi] - map.ys[lo]) * t };
}
var LOOP = [[8,60],[8,84],[26,104],[52,104],[78,104],[100,88],[100,60],[100,32],[122,16],[148,16],[174,16],[192,36],[192,60],[192,84],[174,104],[148,104],[122,104],[100,88],[100,60],[100,32],[78,16],[52,16],[26,16],[8,36],[8,60]];  /* #loop re-based at its left extreme, heading down */

function buildSnake() {
  if (!snakeOn) return;
  var F = film.getBoundingClientRect(), fy0 = F.top + (window.scrollY || 0), W = film.clientWidth, H = film.offsetHeight;
  var LVH = heroFrame.offsetHeight || window.innerHeight;
  var heroTop = pageTop(hero);
  var box = layoutFilm();
  var gut = parseFloat(getComputedStyle(stage).paddingLeft) || 20;
  var xr = parseFloat(getComputedStyle(root).getPropertyValue('--rail')) || (gut * .5 + 1);
  var A = Math.min(4, gut * .2);
  var frameRestTop = heroTop + PIN * LVH - LVH;          /* the frame's page top once it has un-stuck */
  /* the curl, frame-local: M -> S -> the rail, arriving vertical at (xr, K*LVH) */
  var M = [box.mx, box.my], u = M[0] - xr, dd = K * LVH - M[1];
  var Apt = [xr + .38 * u, M[1] + .45 * dd], c1 = [M[0] - .22 * u, M[1] + .40 * dd], c2 = [xr + .62 * u, M[1] + .10 * dd];
  var c3 = [Apt[0] + .7 * (Apt[0] - c2[0]), Apt[1] + .7 * (Apt[1] - c2[1])], c4 = [xr, M[1] + .72 * dd], R0f = [xr, K * LVH];
  snkCurl.path.setAttribute('d', 'M' + f(M) + ' C' + f(c1) + ' ' + f(c2) + ' ' + f(Apt) + ' C' + f(c3) + ' ' + f(c4) + ' ' + f(R0f));
  snkc.setAttribute('width', box.bw); snkc.setAttribute('height', box.bh); snkc.setAttribute('viewBox', '0 0 ' + box.bw + ' ' + box.bh);
  /* the storymark's rect and the loop mapped into it (measured from mark-720.webp: centreline extremes at .090/.910 of w, .161/.839 of h) */
  var img = markAct.querySelector('.storymark'), R = img.getBoundingClientRect();
  var w = R.width, h = R.height, Rl = R.left - F.left, Rt = R.top + (window.scrollY || 0) - fy0;
  var kx = w * .00445, ky = h * .00770;
  function P(s) { return [Rl + w * .090 + (s[0] - 8) * kx, Rt + h * .161 + (s[1] - 16) * ky] }
  var Ept = P([8, 60]);                                   /* the entry: the left lobe's left extreme, tangent straight down */
  var ld = 'M' + f(P(LOOP[0])); for (var i = 1; i < LOOP.length; i += 3) ld += ' C' + f(P(LOOP[i])) + ' ' + f(P(LOOP[i + 1])) + ' ' + f(P(LOOP[i + 2])); ld += ' Z';
  snkLoop.path.setAttribute('d', ld);
  /* the rail: from R0 (the curl's end in page space) through the beats to S0, then the entry cubic */
  var R0 = [xr, frameRestTop + K * LVH - fy0], S0 = [xr, Ept[1] - 1.15 * h];
  var keys = [];
  film.querySelectorAll('.band:not(.band--hero) .band__in').forEach(function (b) { keys.push([xr + A, pageTop(b) - fy0]) });           /* a crest toward each headline */
  film.querySelectorAll('.act:not(.act--still):not(.act--mark):not(.act--word)').forEach(function (a) { keys.push([xr - A, offTop(a)]) }); /* a trough at each prop */
  keys = keys.filter(function (k) { return k[1] > R0[1] + 60 && k[1] < S0[1] - .25 * LVH }).sort(function (a, b) { return a[1] - b[1] });
  var pts = [R0], sign = 1;
  for (i = 0; i < keys.length; i++) {
    var prev = pts[pts.length - 1], gap = keys[i][1] - prev[1];
    if (gap < 24) continue;
    var n = Math.floor(gap / (.6 * LVH));                 /* long gaps wander on their own, alternating sides */
    for (var j = 1; j <= n; j++) { sign = -sign; pts.push([xr + sign * A, prev[1] + gap * j / (n + 1)]) }
    pts.push(keys[i]); sign = keys[i][0] > xr ? 1 : -1;
  }
  pts.push([xr, S0[1] - .25 * LVH]); pts.push(S0);       /* the last half wave damps to the rail */
  var rd = 'M' + f(R0) + crCubics(pts) + ' C' + f([xr, Ept[1] - .5 * h]) + ' ' + f([Ept[0], Ept[1] - .6 * h]) + ' ' + f(Ept);
  snkLine.path.setAttribute('d', rd);
  snk.setAttribute('width', W); snk.setAttribute('height', H); snk.setAttribute('viewBox', '0 0 ' + W + ' ' + H);
  /* lengths and maps */
  var Ls = snkLine.path.getTotalLength(), Ll = snkLoop.path.getTotalLength(), Lc = snkCurl.path.getTotalLength();
  if (!Ls || !Ll || !Lc) { snakeRebuildSoon(); return }   /* not laid out yet (display:none a frame ago) */
  var maps = { line: sample(snkLine.path, Math.max(300, Math.round(Ls / 8))), loop: sample(snkLoop.path, 120), curl: sample(snkCurl.path, 80) };
  setVar(snkLine.g, '--L', Ls, 0); setVar(snkLoop.g, '--L', Ll, 0); setVar(snkCurl.g, '--L', Lc, 0);
  /* the colour: green (stop .40) at the mark's centre, yellow (stop .26, what #infg shows at the left extreme) at the entry; about 1.6 screens per cycle */
  var markPageY = frameRestTop + box.my - fy0, span = Ept[1] - markPageY;
  var cycles = Math.max(1, Math.round(span / (1.6 * LVH) + .14)), Pp = span / (cycles - .14);
  var y1 = markPageY - .40 * Pp;
  [snkG.g, snkG.gl].forEach(function (g) { g.setAttribute('y1', y1.toFixed(1)); g.setAttribute('y2', (y1 + Pp).toFixed(1)) });
  var y1c = y1 + fy0 - frameRestTop;                        /* the same phase in the frame's own space */
  [snkG.gc, snkG.glc].forEach(function (g) { g.setAttribute('y1', y1c.toFixed(1)); g.setAttribute('y2', (y1c + Pp).toFixed(1)) });
  var old = SN;
  SN = { fy0: fy0, heroTop: heroTop, LVH: LVH, frameRestTop: frameRestTop, box: box, M: M, R0: R0, E: Ept, w: w, h: h, Ls: Ls, Ll: Ll, Lc: Lc, maps: maps,
         s0: heroTop + (PIN - 1) * LVH, shownL: 0, shownLoop: 0, shownCurl: 0, tipY: 0 };
  /* a rebuild keeps the drawn end where the reader's eye is: re-derive shown from the same reading line, no lerp across a geometry change */
  if (old) { var ty = (window.scrollY || 0) + K * LVH - fy0; SN.shownL = ty <= R0[1] ? 0 : atY(maps.line, Math.min(ty, Ept[1])); SN.shownLoop = clamp((ty - Ept[1]) / (LOOP_RUN * h), 0, 1); SN.shownCurl = old.shownCurl }
  snakeDraw(performance.now(), true);
  function f(p) { return p[0].toFixed(1) + ' ' + p[1].toFixed(1) }
}

/* ---- the drive: one rAF loop, kicked by scroll, lerping like tick() ---- */
var snakeRaf = null, snakeLast = 0;
function snakeKick() { if (snakeOn && SN && snakeRaf === null && !document.hidden) snakeRaf = requestAnimationFrame(snakeTick) }
function snakeTick(now) {
  var dt = Math.min(100, now - (snakeLast || now)); snakeLast = now;
  var busy = snakeDraw(now, false, dt);
